"use client";

import { useState } from "react";
import { BrowserWalletProvider, connectBrowserWallet, getProvider, WalletName, walletInstallUrls } from "../lib/clientWallet";

const wallets: Array<{ name: WalletName; mark: string; tone: string }> = [
  { name: "Phantom", mark: "P", tone: "#a98bff" },
  { name: "Solflare", mark: "S", tone: "#ff9c38" },
  { name: "Backpack", mark: "B", tone: "#ff5b50" },
];

export default function WalletPicker({ onClose, onConnected }: { onClose: () => void; onConnected: (provider: BrowserWalletProvider, address: string) => void | Promise<void> }) {
  const [status, setStatus] = useState("");

  async function choose(name: WalletName) {
    if (!getProvider(name)) { window.open(walletInstallUrls[name], "_blank", "noopener,noreferrer"); setStatus(`${name.toUpperCase()} IS NOT INSTALLED`); return; }
    try {
      setStatus(`CONNECTING ${name.toUpperCase()}...`);
      const result = await connectBrowserWallet(name);
      await onConnected(result.provider, result.address);
    } catch (error) {
      setStatus(error instanceof Error && /reject/i.test(error.message) ? "CONNECTION CANCELLED" : "CONNECTION FAILED");
    }
  }

  return <div className="bulleWalletModal" role="dialog" aria-modal="true" aria-label="Connect a Solana wallet"><section><header><div><small>BULL HUB // SOLANA</small><h2>CONNECT WALLET</h2><p>Choose a wallet. You will always approve transactions inside your wallet.</p></div><button onClick={onClose}>×</button></header><div className="bulleWalletChoices">{wallets.map(wallet=>{const installed=Boolean(getProvider(wallet.name));return <button key={wallet.name} onClick={()=>void choose(wallet.name)}><i style={{"--wallet-tone":wallet.tone} as React.CSSProperties}>{wallet.mark}</i><span><b>{wallet.name}</b><small>{installed?"READY TO CONNECT":"INSTALL WALLET"}</small></span><strong>{installed?"CONNECT":"GET ↗"}</strong></button>})}</div>{status&&<p className="bulleWalletStatus">{status}</p>}<footer>No seed phrase or private key is ever requested by Bull Hub.</footer></section></div>;
}
